const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const key='elsewhere-preview-v1';let stored={};try{stored=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
let state={theme:'vermilion',mode:'auto',name:'',saved:[],completed:[],notes:[],collections:[],custom:[],tickets:[],capsules:[],surprise:2,...stored};let tab='For you',filter='All',search='',timer=null,deadline=0,left=300,activeId=null,install=null;
const themes={vermilion:'#ee493b',cobalt:'#1765ec',plum:'#914276',graphite:'#e66a24'};
const icons={discover:'⌂',journeys:'⌁',create:'＋',you:'○',rabbit:'◎',twist:'⚑',skill:'◇',history:'◷',map:'⌘',saved:'▱'};
const experiences=[
{id:'memory',type:'Rabbit Hole',title:'Can you trust your memory?',desc:'Explore how remembering is also a little act of invention.',format:'Experiment',minutes:5,topic:'Mind',art:'memory',steps:['Read a short list of words, then hide it.','Recall as many as you can without looking.','Notice what your brain added, omitted, or grouped together.'],prompt:'What surprised you about what you remembered?'},
{id:'sound',type:'Rabbit Hole',title:'Hear it differently',desc:'Two tones, one small change. Listen closely and explore what you notice.',format:'Audio',minutes:3,topic:'Science',art:'sound',steps:['Use a comfortable volume.','Play two short tones and compare their pitch.','Describe the difference before replaying them.'],prompt:'How did paying attention change what you heard?'},
{id:'story',type:'Skill Arcade',title:'Make a one-minute story',desc:'One ordinary object. Three sentences. A whole new world.',format:'Writing',minutes:15,topic:'Creativity',art:'story',steps:['Choose an everyday object nearby.','Write a beginning that makes it unusual.','Add a turning point and an ending in two more sentences.'],prompt:'Write your three-sentence story here.'},
{id:'route',type:'Plot Twist',title:'Change your usual route',desc:'Take a familiar walk a little differently. Find one detail you have never noticed.',format:'Outdoors',minutes:20,topic:'Places',art:'walk',steps:['Choose a familiar, accessible public route in daylight.','Take a comfortable alternative or pause at a different spot.','Notice three sounds, two textures, and one unexpected detail.'],prompt:'What did you notice when you changed your route?'},
{id:'design',type:'Skill Arcade',title:'Redesign one small thing',desc:'Find a tiny everyday frustration and sketch a better version.',format:'Project',minutes:25,topic:'Design',art:'design',steps:['Identify one small thing you use regularly.','Describe who it helps and what feels awkward.','Sketch three improvements, then choose the simplest.'],prompt:'Describe or paste a link to your idea.'},
{id:'perspective',type:'Rabbit Hole',title:'What changes your mind?',desc:'Explore one belief through evidence, experience, and another person’s view.',format:'Reflection',minutes:10,topic:'People',art:'design',steps:['Write a belief you hold lightly.','Give the strongest fair argument for a different view.','Write what evidence could change your mind.'],prompt:'I used to think… Now I wonder…'},
{id:'quiz',type:'Rabbit Hole',title:'A quick curiosity check',desc:'Three questions that reward noticing, not memorizing.',format:'Quiz',minutes:3,topic:'Science',art:'memory',steps:[],prompt:'What question would you like to investigate next?'},
{id:'two',type:'Plot Twist',title:'Same object, different stories',desc:'A two-person quest: compare what an ordinary object means to each of you.',format:'Together',minutes:15,topic:'People',art:'story',steps:['Invite a friend and pick an ordinary object.','Each write a memory or invented story about it independently.','Read both aloud and compare what you noticed.'],prompt:'What did the other person see that you missed?'},
{id:'simulate',type:'Rabbit Hole',title:'Small choices, compounding change',desc:'Adjust a daily improvement and explore how repeated choices accumulate.',format:'Simulation',minutes:5,topic:'Science',art:'design',steps:[],prompt:'Where could one small repeated action matter to you?'}];
function all(){return [...experiences,...state.custom]};function esc(t){return String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function persist(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Storage is full. Export a backup in Your space.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function appearance(){document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.mode=state.mode==='auto'?(matchMedia('(prefers-color-scheme:dark)').matches?'night':'day'):state.mode;document.querySelector('meta[name=theme-color]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim()}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',appearance);
function nav(){const page=location.hash.slice(1)||'discover';$('#sidebar').innerHTML=`<a href="#discover" class="sidebar-brand">elsewhere<span class="accent">.</span></a>${[['discover','Discover'],['journeys','Your journeys'],['rabbit','Rabbit Hole'],['twist','Plot Twist'],['skill','Skill Arcade'],['history','Version History'],['map','Curiosity Map'],['saved','Saved & collections'],['create','Create'],['you','Your space']].map(([id,t])=>`<button class="navitem ${page===id?'active':''}" data-nav="${id}"><span class="nav-symbol">${icons[id]}</span>${t}</button>`).join('')}<div class="side-foot"><b>A little outside your usual.</b><br>A working browser prototype.<br>Your entries stay on this device.</div>`;$('#bottom').innerHTML=[['discover','Discover'],['journeys','Journeys'],['create','Create'],['you','You']].map(([id,t])=>`<button class="${page===id?'active':''}" data-nav="${id}"><span class="nav-symbol">${icons[id]}</span>${t}</button>`).join('');$('.avatar').textContent=(state.name||'A')[0].toUpperCase()}
function card(e){return `<article class="card"><button class="art ${e.art||'story'}" data-open="${esc(e.id)}" aria-label="Explore ${esc(e.title)}"></button><div class="card-body"><span class="eyebrow accent">${esc(e.type)}</span><h3><a href="#experience/${esc(e.id)}">${esc(e.title)}</a></h3><p>${esc(e.desc)}</p><div class="card-actions"><span class="meta">${e.minutes} min · ${esc(e.format)}</span><button class="bookmark ${state.saved.includes(e.id)?'saved':''}" data-save="${esc(e.id)}" aria-label="${state.saved.includes(e.id)?'Unsave':'Save'} ${esc(e.title)}">${state.saved.includes(e.id)?'▣':'▱'}</button></div></div></article>`}
const branch=`<svg viewBox="0 0 200 240" fill="none" aria-hidden="true"><path d="M0 120H45Q70 120 70 95V65Q70 40 95 40H170M70 90Q70 120 100 120H170M45 120Q70 120 70 150V175Q70 200 95 200H170" stroke="currentColor" stroke-width="2"/><circle cx="170" cy="40" r="9" fill="currentColor"/><circle cx="170" cy="120" r="9" fill="currentColor"/><circle cx="170" cy="200" r="9" fill="currentColor"/><circle cx="5" cy="120" r="5" fill="currentColor"/></svg>`;
function tool(id,s,t){return `<button class="tool" data-action="${id}"><span>${s}</span><strong>${t}</strong></button>`}
function discover(){return `<section class="intro"><div><p class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})} / A LITTLE OUTSIDE YOUR USUAL</p><h1>A good day<br>to <span class="accent">wonder.</span></h1><p>Follow a thought. Try a small adventure.<br>Find a little more of yourself.</p></div><button class="button" data-action="surprise">✦ Surprise me <span class="accent">↗</span></button></section><div class="tabs" role="tablist">${['For you','Explore','Saved'].map(t=>`<button role="tab" aria-selected="${tab===t}" class="${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${tab==='For you'?`<div class="discovery-grid"><article class="feature"><div class="feature-copy"><span class="eyebrow accent">◎ Rabbit Hole · TODAY’S CURIOSITY</span><h2>What changes<br>your mind?</h2><p>New evidence. A different experience.<br>Another way of seeing things.</p><button class="arrow" data-open="perspective" aria-label="Explore what changes your mind">↗</button></div><button class="branch-art" data-open="perspective" aria-label="Explore connected perspectives">${branch}</button></article><article class="mini-feature"><span class="eyebrow">⚑ Plot Twist / 20 MINUTES</span><h3>Take the<br>unfamiliar route.</h3><p>One small change to your usual day can reveal something unexpected.</p><div class="row between"><span class="eyebrow">REAL-WORLD QUEST</span><button class="button" data-open="route">Try it ↗</button></div></article></div><section class="section"><div class="section-title"><h2>Make room for making.</h2><button class="text-link" data-nav="skill">Skill Arcade ↗</button></div><div class="cards">${['story','design','sound'].map(id=>card(all().find(x=>x.id===id))).join('')}</div></section><section class="section"><div class="section-title"><h2>You, in progress.</h2><button class="text-link" data-nav="history">Version History ↗</button></div><div class="reflection"><span class="stamp">◷</span><div><h3>What surprised you about yourself this week?</h3><p class="muted">A quick reflection to capture what shifted, big or small.</p></div><button class="arrow" data-action="note" aria-label="Write a reflection">↗</button></div></section><section class="section"><div class="section-title"><h2>More ways to explore</h2></div><div class="tools">${tool('map','⌘','Curiosity Map')}${tool('remix','⤨','Remix Studio')}${tool('field','✎','Field Notes')}${tool('capsule','◴','Personal Capsules')}</div></section>`:tab==='Saved'?saved():explore()}`}
function explore(){const list=all().filter(e=>(filter==='All'||e.topic===filter||e.format===filter)&&(e.title+' '+e.desc+' '+e.type).toLowerCase().includes(search.toLowerCase()));return `<input class="search" id="search" type="search" value="${esc(search)}" placeholder="Search curiosities, projects, or ideas…" aria-label="Search experiences"><div class="filters">${['All','Mind','Science','Creativity','People','Places','Design','Audio','Quiz','Simulation','Together'].map(t=>`<button class="chip ${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="cards" id="results">${list.map(card).join('')||'<div class="empty">No matches. Try a different topic or search.</div>'}</div>`}
function head(title,copy){return `<div class="page-head"><p class="eyebrow accent" style="margin-bottom:12px">ELSEWHERE / YOUR SPACE TO EXPLORE</p><h1>${title}</h1><p>${copy}</p></div>`}
function journeys(){const completed=all().filter(e=>state.completed.includes(e.id));return head('Your curiosity, in motion.','Pick up where you left off, or follow a different thread.')+`<div class="tools">${tool('rabbit','◎','Rabbit Hole')}${tool('twist','⚑','Plot Twist')}${tool('skill','◇','Skill Arcade')}${tool('history','◷','Version History')}</div><section class="section"><div class="section-title"><h2>Return tickets</h2></div>${state.tickets.length?state.tickets.map(t=>`<div class="collection"><div class="row between"><h3>${esc(all().find(e=>e.id===t.id)?.title||t.id)}</h3><button class="button" data-open="${esc(t.id)}">Resume ↗</button></div><p>${esc(t.note)}</p></div>`).join(''):'<div class="empty">Pause any experience with a Return Ticket.<br>Your next step will be here when you return.</div>'}</section><section class="section"><div class="section-title"><h2>Completed experiences · ${completed.length}</h2></div><div class="cards">${completed.map(card).join('')||'<div class="empty">Your first completed experience starts a trail.</div>'}</div></section>`}
function history(){return head('You, in progress.','A timeline of thoughts, new perspectives, and things you tried.')+`<div class="row"><button class="button primary" data-action="note">＋ Add reflection</button><button class="button" data-action="capsule">◴ Personal capsules</button></div>${state.notes.length?`<div class="timeline">${[...state.notes].reverse().map(n=>`<article class="entry"><small>${new Date(n.date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})} · ${esc(n.kind)}</small><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><button class="text-link" data-delete-note="${n.id}">Delete entry</button></article>`).join('')}</div>`:'<div class="empty section">Your story starts with a small observation.<br>Add a reflection, finish an experience, or capture a field note.</div>'}`}
function saved(){return `${location.hash==='#saved'?head('Worth coming back to.','Bookmarks and collections for your next curious moment.'):''}<div class="row between"><h2>Saved experiences</h2><button class="button" data-action="collection">＋ Collection</button></div><div class="cards section">${all().filter(e=>state.saved.includes(e.id)).map(card).join('')||'<div class="empty">Tap a bookmark on an experience to save it here.</div>'}</div><section class="section"><h2>Collections</h2>${state.collections.map(c=>`<div class="collection"><div class="row between"><h3>${esc(c.title)}</h3><button class="text-link" data-action="addcollection" data-id="${c.id}">Add saved items</button></div><p>${c.items.length} experiences</p><div class="row">${c.items.map(id=>`<button class="chip" data-open="${id}">${esc(all().find(e=>e.id===id)?.title||id)}</button>`).join('')}</div></div>`).join('')||'<p class="muted section">Create a collection for discoveries that belong together.</p>'}</section>`}
function create(){return head('Turn a spark into something.','Capture a thought, make an experience, or give an idea a second life.')+`<div class="tools">${tool('field','✎','Field Notes')}${tool('remix','⤨','Remix Studio')}${tool('builder','＋','Experience Builder')}${tool('capsule','◴','Personal Capsules')}${tool('two','♧','Two-Person Quest')}${tool('perspective','↔','Perspective Switch')}${tool('collection','▱','New Collection')}${tool('map','⌘','Curiosity Map')}</div><div class="notice">This preview saves your entries on this browser. Two-person quests are designed to do together in person; online accounts and collaboration are not connected.</div><section class="section"><h2>Your creations</h2><div class="cards section">${state.custom.map(card).join('')||'<div class="empty">Build your first experience. It will appear here and in Explore.</div>'}</div></section>`}
function you(){return head(state.name?`${esc(state.name)}’s corner.`:'A space that feels like you.','Choose your look, shape your discoveries, and keep a copy of your progress.')+`<div class="settings-grid"><section class="panel"><h3>Four ways to feel at home</h3><p class="muted">Same discoveries. Your own atmosphere.</p><div class="theme-list section">${Object.entries(themes).map(([t,c])=>`<button class="theme-button ${state.theme===t?'active':''}" data-theme="${t}"><i class="swatch" style="background:${c}"></i>${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><label>Appearance</label><div class="row">${['day','night','auto'].map(m=>`<button class="chip ${state.mode===m?'active':''}" data-mode="${m}">${m==='auto'?'Follow device':m==='day'?'☀ Day':'☾ Night'}</button>`).join('')}</div></section><section class="panel"><h3>Make it personal</h3><label for="name">What should we call you?</label><input id="name" maxlength="40" value="${esc(state.name)}" placeholder="Your name"><label for="surprise">Surprise dial</label><input id="surprise" type="range" min="1" max="3" value="${state.surprise}"><div class="row between muted"><small>Familiar</small><small>Curious</small><small>Adventurous</small></div><label>Notifications & display</label><div class="row"><button class="button" data-action="notifications">Enable timer alerts</button><button class="button" data-action="fullscreen">Full screen</button></div></section><section class="panel"><h3>Your trail so far</h3><div class="row between"><div><div class="stat">${state.completed.length}</div><small>experiences</small></div><div><div class="stat">${state.notes.length}</div><small>notes</small></div><div><div class="stat">${state.saved.length}</div><small>saved</small></div></div></section><section class="panel"><h3>Keep your discoveries</h3><p class="muted">Your data is stored locally, without a connected account. Export a backup to keep or transfer it.</p><div class="row section"><button class="button" data-action="export">↓ Export data</button><label class="button" style="margin:0;cursor:pointer">↑ Restore backup<input type="file" id="import" accept="application/json" hidden></label></div></section></div>`}
function map(){const seen=all().filter(e=>state.completed.includes(e.id)||state.saved.includes(e.id));return head('Follow the connections.','Your saved and completed experiences form a map of what catches your attention.')+`<div class="map"><button class="map-node center" data-nav="discover">Your curiosity</button>${(seen.length?seen:experiences.slice(0,4)).map(e=>`<button class="map-node" data-open="${e.id}">${esc(e.topic)} · ${esc(e.title)}</button>`).join('')}</div><div class="notice">${seen.length?'Nodes reflect your saved and completed experiences.':'Example connections are shown until you save or complete experiences.'} Select a node to follow its experience.</div>`}
function render(){nav();const p=location.hash.slice(1)||'discover';let html;if(p.startsWith('experience/')){html=discover();setTimeout(()=>openExperience(p.split('/')[1]),0)}else if(p==='discover')html=discover();else if(p==='journeys')html=journeys();else if(p==='history')html=history();else if(p==='saved')html=saved();else if(p==='create')html=create();else if(p==='you')html=you();else if(p==='map')html=map();else{const names={rabbit:'Rabbit Hole',twist:'Plot Twist',skill:'Skill Arcade'};const n=names[p];html=n?head(n,n==='Rabbit Hole'?'Questions worth following. Experiments worth trying.':n==='Plot Twist'?'Small departures from the ordinary.':'Learn by making something real.')+`<div class="cards">${all().filter(e=>e.type===n).map(card).join('')}</div>`:discover()}$('#main').innerHTML=html;appearance()}
function go(p){$('#dialog').close();if(location.hash==='#'+p)render();else location.hash=p}
function modal(title,html){$('#dialogBody').innerHTML=`<div class="dialog-top"><h2>${esc(title)}</h2><button class="icon" data-action="close" aria-label="Close dialog">×</button></div>${html}`;if(!$('#dialog').open)$('#dialog').showModal()}
function form(title,kind,prompt='',initial=''){modal(title,`<form id="noteForm"><label for="noteTitle">Title</label><input id="noteTitle" maxlength="100" value="${esc(title)}" required><label for="noteText">${esc(prompt||'What would you like to remember?')}</label><textarea id="noteText" required placeholder="Start anywhere…">${esc(initial)}</textarea><input type="hidden" id="kind" value="${esc(kind)}"><button class="button primary section" type="submit">Save ${kind==='Field note'?'note':'reflection'} ↗</button></form>`)}
function openExperience(id){const e=all().find(x=>x.id===id);if(!e)return;activeId=id;modal(e.type,`<div class="detail"><div class="art detail-art ${e.art||'story'}"></div><div class="row between"><span class="eyebrow accent">${esc(e.format)} / ${e.minutes} MIN</span><button class="bookmark ${state.saved.includes(id)?'saved':''}" data-save="${id}" aria-label="Save experience">${state.saved.includes(id)?'▣':'▱'}</button></div><h2>${esc(e.title)}</h2><p>${esc(e.desc)}</p>${e.steps.length?`<ol>${e.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`:''}<div id="interactive">${id==='memory'?'<button class="button primary" data-action="memory">Start memory experiment</button>':id==='quiz'?'<button class="button primary" data-action="quiz">Take the quiz</button>':id==='sound'?'<button class="button primary" data-action="audio">▶ Play two tones</button>':id==='simulate'?'<label for="rate">Daily improvement: <span id="rateValue">1%</span></label><input id="rate" type="range" min="0" max="3" step="0.1" value="1"><p>After 365 repetitions: <strong id="simResult">37.8×</strong> your starting value.</p><small>A mathematical model, not a forecast of human performance.</small>':''}</div><div class="row"><button class="button primary" data-action="complete" data-id="${id}">${state.completed.includes(id)?'✓ Completed':'Mark complete'}</button><button class="button" data-action="reflect" data-id="${id}">✎ Reflect</button><button class="button" data-action="ticket" data-id="${id}">Return ticket</button><button class="button" data-action="timer" data-id="${id}">◷ Timer</button></div><div id="timerArea"></div></div>`)}
function timerDraw(){if(!$('#timerReadout'))return;$('#timerReadout').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`}
function alertDone(){toast('Session complete. Take a moment to notice what changed.');if('Notification'in window&&Notification.permission==='granted'){if(navigator.serviceWorker?.controller)navigator.serviceWorker.ready.then(r=>r.showNotification('Elsewhere',{body:'Your session is complete.'})).catch(()=>{});else try{new Notification('Elsewhere',{body:'Your session is complete.'})}catch{}}}
function toggleTimer(){if(timer){clearInterval(timer);timer=null;left=Math.max(0,Math.ceil((deadline-Date.now())/1000));}else{if(left<=0)left=300;deadline=Date.now()+left*1000;timer=setInterval(()=>{left=Math.max(0,Math.ceil((deadline-Date.now())/1000));timerDraw();if(!left){clearInterval(timer);timer=null;alertDone()}},250)}const b=$('[data-action="timerToggle"]');if(b)b.textContent=timer?'Pause':'Start';timerDraw()}
let quizIndex=0,quizScore=0;const questions=[['Which is a stronger way to investigate an idea?',['Look for evidence that could disprove it','Only collect examples that agree'],0],['In the compounding model, 0% daily change means…',['The starting value stays the same','It doubles'],0],['A useful reflection captures…',['Only whether you succeeded','What you noticed and might try next'],1]];
function quizDraw(){if(quizIndex===questions.length){$('#interactive').innerHTML=`<h3>${quizScore} of ${questions.length}</h3><p>Curiosity grows through testing ideas and noticing what happens.</p>`;return}const q=questions[quizIndex];$('#interactive').innerHTML=`<p class="eyebrow">QUESTION ${quizIndex+1} / 3</p><h3>${q[0]}</h3>${q[1].map((a,i)=>`<button class="answer" data-answer="${i}">${a}</button>`).join('')}`}
document.addEventListener('click',async ev=>{const el=ev.target.closest('button,a');if(!el)return;if(el.dataset.nav)return go(el.dataset.nav);if(el.dataset.open)return openExperience(el.dataset.open);if(el.dataset.theme){state.theme=el.dataset.theme;persist();render();return}if(el.dataset.mode){state.mode=el.dataset.mode;persist();render();return}if(el.dataset.tab){tab=el.dataset.tab;render();return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.save){const id=el.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();el.classList.toggle('saved',state.saved.includes(id));el.textContent=state.saved.includes(id)?'▣':'▱';toast(state.saved.includes(id)?'Saved to your discoveries':'Bookmark removed');return}if(el.dataset.deleteNote){state.notes=state.notes.filter(n=>String(n.id)!==el.dataset.deleteNote);persist();render();return}if(el.dataset.answer!==undefined){if(+el.dataset.answer===questions[quizIndex][2])quizScore++;quizIndex++;quizDraw();return}const a=el.dataset.action,id=el.dataset.id;if(!a)return;
if(a==='close')return $('#dialog').close();if(a==='appearance')return go('you');if(['rabbit','twist','skill','history','map'].includes(a))return go(a);if(a==='note')return form('Something shifted','Reflection');if(a==='field')return form('A small observation','Field note','What did you notice? Paste links or write a quick thought.');if(a==='reflect'){const e=all().find(x=>x.id===id);return form(e.title,'Reflection',e.prompt)}if(a==='perspective')return openExperience('perspective');if(a==='two')return openExperience('two');
if(a==='complete'){if(!state.completed.includes(id)){state.completed.push(id);state.notes.push({id:Date.now(),date:new Date().toISOString(),kind:'Milestone',title:all().find(e=>e.id===id).title,text:'Completed an experience. A new thread in your story.'});state.tickets=state.tickets.filter(t=>t.id!==id);persist()}el.textContent='✓ Completed';toast('Added to your journeys and Version History');return}
if(a==='surprise'){const choices=all().filter(e=>!state.completed.includes(e.id)&&(state.surprise===1?e.minutes<=10:state.surprise===3?e.minutes>=15:true));return openExperience((choices.length?choices:all())[Math.floor(Math.random()*(choices.length||all().length))].id)}
if(a==='ticket')return modal('Save a return ticket',`<form id="ticketForm" data-id="${id}"><label for="ticketText">Where did you stop? What is next?</label><textarea id="ticketText" required placeholder="Next time, I want to…"></textarea><button class="button primary section">Save return ticket</button></form>`);
if(a==='timer'){left=all().find(e=>e.id===id).minutes*60;if(timer)clearInterval(timer);timer=null;$('#timerArea').innerHTML='<div class="timer" id="timerReadout"></div><div class="row" style="justify-content:center"><button class="button primary" data-action="timerToggle">Start</button><button class="button" data-action="timerReset">Reset</button></div><p class="muted">Timer alerts work while this page remains open.</p>';timerDraw();return}if(a==='timerToggle')return toggleTimer();if(a==='timerReset'){clearInterval(timer);timer=null;left=all().find(e=>e.id===activeId).minutes*60;timerDraw();$('[data-action="timerToggle"]').textContent='Start';return}
if(a==='memory'){$('#interactive').innerHTML='<p id="words" class="panel">River · Window · Lemon · Guitar · Cloud · Bicycle</p><button class="button" data-action="hideWords">I am ready to recall</button>';return}if(a==='hideWords'){$('#interactive').innerHTML='<label for="recall">Which words do you remember?</label><input id="recall" placeholder="Write the words…"><button class="button section" data-action="checkWords">Compare</button>';return}if(a==='checkWords'){const original=['river','window','lemon','guitar','cloud','bicycle'];const response=$('#recall').value.toLowerCase().split(/[^a-z]+/);const correct=original.filter(w=>response.includes(w));$('#interactive').innerHTML=`<h3>You recalled ${correct.length} of 6 words.</h3><p>The words were: River, Window, Lemon, Guitar, Cloud, Bicycle.</p><p>This is a playful observation, not a memory assessment. Try grouping the words into a story next time.</p>`;return}
if(a==='quiz'){quizIndex=0;quizScore=0;return quizDraw()}if(a==='audio'){try{const ctx=new(window.AudioContext||window.webkitAudioContext)();[440,466].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=f;g.gain.value=.04;o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*.9);o.stop(ctx.currentTime+i*.9+.6)});setTimeout(()=>ctx.close(),2300);toast('Two pitches: 440 Hz, then 466 Hz')}catch{toast('Audio is unavailable on this device.')}return}
if(a==='builder'||a==='remix'){const e=experiences[Math.floor(Math.random()*experiences.length)];return modal(a==='remix'?'Give an idea a new life':'Build an experience',`<form id="builderForm"><p class="muted">${a==='remix'?`Starting spark: ${esc(e.title)}. Change its format or take it somewhere new.`:'Create a personal experience to try later.'}</p><label for="buildTitle">Title</label><input id="buildTitle" required maxlength="100" value="${a==='remix'?esc('Remix: '+e.title):''}"><label for="buildType">Journey</label><select id="buildType"><option>Rabbit Hole</option><option>Plot Twist</option><option>Skill Arcade</option></select><label for="buildFormat">Format</label><select id="buildFormat">${['Experiment','Audio','Reading','Quiz','Writing','Project','Outdoors','Conversation','Simulation','Other'].map(x=>`<option>${x}</option>`).join('')}</select><label for="buildSteps">Steps, one per line</label><textarea id="buildSteps" required></textarea><label for="buildMinutes">Minutes</label><input id="buildMinutes" type="number" min="1" max="300" value="15" required><button class="button primary section">Save experience</button></form>`)}
if(a==='capsule')return modal('A note to your future self',`<form id="capsuleForm"><label for="capsuleText">What do you want to revisit?</label><textarea id="capsuleText" required></textarea><label for="capsuleDate">Open on</label><input id="capsuleDate" type="date" min="${new Date().toLocaleDateString('en-CA')}" required><button class="button primary section">Seal capsule</button></form><section class="section">${state.capsules.map(c=>`<div class="collection"><small>Opens ${esc(c.date)}</small><p>${new Date(c.date+'T00:00:00')<=new Date()?esc(c.text):'◴ Sealed until your chosen day'}</p></div>`).join('')}</section><p class="notice">A reflective time capsule, not encrypted storage. Check back here to open it; background reminders are not connected.</p>`);
if(a==='collection')return modal('A collection of possibilities',`<form id="collectionForm"><label for="collectionTitle">Collection name</label><input id="collectionTitle" required maxlength="80" placeholder="Things that surprised me"><button class="button primary section">Create collection</button></form>`);
if(a==='addcollection'){const c=state.collections.find(x=>String(x.id)===id);return modal(c.title,`<form id="collectionItems" data-id="${id}">${state.saved.map(s=>`<label class="row"><input style="width:auto" type="checkbox" name="item" value="${s}" ${c.items.includes(s)?'checked':''}>${esc(all().find(e=>e.id===s)?.title||s)}</label>`).join('')||'<p>Bookmark some experiences first.</p>'}<button class="button primary section">Save collection</button></form>`)}
if(a==='notifications'){if(!('Notification'in window))return toast('Notifications are not supported in this browser.');const permission=await Notification.requestPermission();toast(permission==='granted'?'Timer alerts enabled while the app is open.':'Notifications are off. In-app alerts will still appear.');return}
if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Use your browser’s full-screen or home-screen mode.')}catch{toast('Full screen is unavailable in this browser.')}return}
if(a==='export'){const blob=new Blob([JSON.stringify({app:'Elsewhere',version:1,data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='elsewhere-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
});
document.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target;if(f.id==='noteForm'){state.notes.push({id:Date.now(),date:new Date().toISOString(),kind:$('#kind').value,title:$('#noteTitle').value,text:$('#noteText').value});toast('Added to Version History')}else if(f.id==='ticketForm'){state.tickets=state.tickets.filter(t=>t.id!==f.dataset.id);state.tickets.push({id:f.dataset.id,note:$('#ticketText').value});toast('Your return ticket is ready')}else if(f.id==='builderForm'){state.custom.push({id:'custom-'+Date.now(),type:$('#buildType').value,title:$('#buildTitle').value,desc:'An experience you created.',format:$('#buildFormat').value,minutes:+$('#buildMinutes').value,topic:'Creativity',art:'story',steps:$('#buildSteps').value.split('\n').filter(Boolean),prompt:'What did you discover?'});toast('Your experience is ready to explore')}else if(f.id==='capsuleForm'){state.capsules.push({id:Date.now(),date:$('#capsuleDate').value,text:$('#capsuleText').value});toast('Capsule sealed')}else if(f.id==='collectionForm'){state.collections.push({id:Date.now(),title:$('#collectionTitle').value,items:[]});toast('Collection created')}else if(f.id==='collectionItems'){state.collections.find(c=>String(c.id)===f.dataset.id).items=[...new FormData(f).getAll('item')];toast('Collection updated')}persist();$('#dialog').close();render()});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const pos=e.target.selectionStart;$('#main').innerHTML=discover();$('#search').focus();$('#search').setSelectionRange(pos,pos)}if(e.target.id==='name'){state.name=e.target.value;persist();nav()}if(e.target.id==='surprise'){state.surprise=+e.target.value;persist()}if(e.target.id==='rate'){const value=+e.target.value;$('#rateValue').textContent=value+'%';$('#simResult').textContent=Math.pow(1+value/100,365).toFixed(1)+'×'}});
document.addEventListener('change',async e=>{if(e.target.id!=='import')return;try{const backup=JSON.parse(await e.target.files[0].text());if(backup.app!=='Elsewhere'||backup.version!==1||!backup.data||!Array.isArray(backup.data.notes)||!Array.isArray(backup.data.saved))throw Error();const d=backup.data;if(!themes[d.theme]||!['day','night','auto'].includes(d.mode))throw Error();state={...state,...d};persist();render();toast('Backup restored')}catch{toast('This is not a valid Elsewhere backup.')}});
let start=null;$('#main').addEventListener('touchstart',e=>{if(e.target.closest('input,textarea,select,button,a'))return;start={x:e.changedTouches[0].clientX,y:e.changedTouches[0].clientY}},{passive:true});$('#main').addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;start=null;if(Math.abs(dx)>100&&Math.abs(dy)<50&&location.hash==='#discover'){const ts=['For you','Explore','Saved'];tab=ts[Math.max(0,Math.min(2,ts.indexOf(tab)+(dx<0?1:-1)))];render()}},{passive:true});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});render();
